//! Renders `strings_shared.xml` for the Android app.

use std::path::PathBuf;

use crate::catalog::Entry;
use crate::locale::Locale;
use crate::message::{Forms, Message, Segment};
use crate::model::{ArgName, ArgType, Target};
use crate::validate::Validated;

/// The resource directory of the Android app, relative to the repository root.
pub const RES_DIR: &str = "android/app/src/main/res";
/// The file name that the generator owns in each `values*` directory.
pub const FILE_NAME: &str = "strings_shared.xml";
/// The string that names the language of a generated file, such as `zh-Hans`.
///
/// Android resolves it from the same `values*` directory as the text. Code that
/// formats dates with it therefore uses the language of the text, also when the
/// device language has no translation and Android falls back to `values/`.
/// `locales/` must not declare this key.
pub const LOCALE_TAG_KEY: &str = "locale_tag";

/// Returns the path of the generated file for a language, relative to the
/// repository root. The fallback language uses `values/`.
pub fn path(validated: &Validated<'_>, locale: &Locale) -> PathBuf {
    let dir = if *locale == validated.config.fallback {
        "values".to_owned()
    } else {
        locale.android_values_dir()
    };
    PathBuf::from(RES_DIR).join(dir).join(FILE_NAME)
}

/// Renders the resources of one release language.
pub fn render(validated: &Validated<'_>, locale: &Locale) -> String {
    let mut xml = String::from(
        "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n\
         <!-- Generated by crates/locales from locales/. Do not edit this file. -->\n\
         <resources>\n\
         \x20   <!-- The language of this file. The app formats dates in this language. -->\n",
    );
    // A canonical BCP 47 code holds only ASCII letters, digits and `-`, so it
    // needs no escaping.
    xml.push_str(&format!(
        "    <string name=\"{LOCALE_TAG_KEY}\">{}</string>\n",
        locale.as_str()
    ));
    let mut domain = None;
    for entry in validated.entries_for(Target::Android) {
        let Some(message) = entry.messages.get(locale) else {
            continue;
        };
        if domain != Some(entry.domain) {
            domain = Some(entry.domain);
            xml.push_str(&format!("    <!-- {} -->\n", entry.domain));
        }
        render_entry(&mut xml, entry.key.as_str(), entry.meta, message);
    }
    xml.push_str("</resources>\n");
    xml
}

fn render_entry(xml: &mut String, name: &str, meta: &Entry, message: &Message) {
    match message.forms() {
        Forms::Single(segments) => {
            let body = format_segments(meta, &segments);
            xml.push_str(&format!("    <string name=\"{name}\">{body}</string>\n"));
        }
        Forms::Plural { forms, .. } => {
            xml.push_str(&format!("    <plurals name=\"{name}\">\n"));
            for (category, segments) in &forms {
                let body = format_segments(meta, segments);
                xml.push_str(&format!(
                    "        <item quantity=\"{category}\">{body}</item>\n"
                ));
            }
            xml.push_str("    </plurals>\n");
        }
    }
}

/// Formats one text form as the body of an Android string resource.
fn format_segments(meta: &Entry, segments: &[Segment]) -> String {
    let formatted = !meta.args.is_empty();
    let mut out = String::new();
    for (index, segment) in segments.iter().enumerate() {
        match segment {
            Segment::Text(text) => escape_text(&mut out, text, formatted, index == 0),
            Segment::Arg(name) | Segment::Count(name) => out.push_str(&specifier(meta, name)),
        }
    }
    out
}

/// Returns the positional format specifier of an argument, such as `%2$d`.
fn specifier(meta: &Entry, name: &ArgName) -> String {
    let position = meta
        .position(name)
        .expect("validation rejects messages with undeclared arguments");
    let conversion = match meta.args[name] {
        ArgType::String => 's',
        ArgType::Int => 'd',
    };
    format!("%{position}${conversion}")
}

/// Escapes literal text for an Android string resource.
///
/// `formatted` doubles `%`, because Android formats a string with arguments.
/// `at_start` escapes a leading `@` or `?`, which Android reads as a reference.
fn escape_text(out: &mut String, text: &str, formatted: bool, at_start: bool) {
    for (index, c) in text.chars().enumerate() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\'' => out.push_str("\\'"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '%' if formatted => out.push_str("%%"),
            '@' | '?' if at_start && index == 0 => {
                out.push('\\');
                out.push(c);
            }
            _ => out.push(c),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn escaped(text: &str, formatted: bool) -> String {
        let mut out = String::new();
        escape_text(&mut out, text, formatted, true);
        out
    }

    #[test]
    fn escapes_android_special_characters() {
        assert_eq!(escaped("it's \"ok\"", false), "it\\'s \\\"ok\\\"");
        assert_eq!(escaped("a\nb\\c", false), "a\\nb\\\\c");
        assert_eq!(escaped("<b> & </b>", false), "&lt;b&gt; &amp; &lt;/b&gt;");
        assert_eq!(escaped("@home ?", false), "\\@home ?");
        assert_eq!(escaped("?x", false), "\\?x");
    }

    #[test]
    fn doubles_percent_only_in_formatted_strings() {
        assert_eq!(escaped("100%", false), "100%");
        assert_eq!(escaped("100%", true), "100%%");
    }
}
